//! The SpecFluxFrame methods C inherits from CmpFrame, checked against the
//! C library (`specflux_cmp_oracle/cases.rs`, generated by
//! `tools/oracle_fixtures/specflux_cmp_probe.c`): picking one axis keeps its
//! SpecFrame or FluxFrame class, and a SpecFluxFrame template matches the
//! components of a plain CmpFrame (specfluxframe.c `Match`, `SubFrame`).

use crate::common::native_dump;
use starlink_ast::frames::FrameSearch;
#[path = "specflux_cmp_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::frames::{
    CmpFrame, FluxFrame, FluxSystem, Frame, FrameRef, SpecFluxFrame, SpecFrame, SpecSystem,
    pick_axes,
};

fn spec(unit: &str) -> SpecFrame {
    let mut s = SpecFrame::new(SpecSystem::Freq);
    s.set_unit(1, unit).unwrap();
    s
}

fn flux() -> FluxFrame {
    let mut f = FluxFrame::with_spec_val(1.4e9, None);
    f.set_system(FluxSystem::FluxDen).unwrap();
    f
}

fn class(f: &dyn Frame) -> &'static str {
    if f.as_any().is::<SpecFrame>() {
        "SpecFrame"
    } else if f.as_any().is::<FluxFrame>() {
        "FluxFrame"
    } else if f.as_any().is::<CmpFrame>() {
        "CmpFrame"
    } else {
        "other"
    }
}

#[test]
fn single_axis_picks_match_the_c_library() {
    for &(swapped, axis, want_class, label, unit) in cases::PICKS {
        let mut s = SpecFluxFrame::new(spec("GHz"), flux());
        if swapped {
            s.perm_axes(&[2, 1]).unwrap();
        }
        let (picked, _) = pick_axes(&s, &[axis]).unwrap();
        assert_eq!(
            (
                class(picked.as_ref()),
                picked.label(1).unwrap(),
                picked.unit(1).unwrap()
            ),
            (want_class, label.to_string(), unit.to_string()),
            "swapped {swapped} axis {axis}"
        );
    }
}

#[test]
fn template_matches_a_plain_cmpframe_as_c_does() {
    let mut target = CmpFrame::new(Box::new(spec("GHz")), Box::new(flux()));
    let template = SpecFluxFrame::new(spec("MHz"), flux());
    let found = target.find_frame_template(&template, "").unwrap();
    let got = found.map(|fs| {
        let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
        let out = map
            .transform(
                &PointSet::from_columns(&[&[1.4], &[1.0e-26]]).unwrap(),
                true,
            )
            .unwrap();
        let p = out.point(0);
        (class(fs.frame(FrameRef::Current).unwrap()), [p[0], p[1]])
    });
    assert_eq!(got, cases::FOUND);
}

/// A SpecFluxFrame is written as the CmpFrame it is in C, with its axis
/// permutation, components and `IsA CmpFrame` marker, and reads back to the
/// same Frame. `specfluxframe_swapped.native` is the C library's `astShow`
/// of the Frame built here.
#[test]
#[cfg_attr(ast_dist_tier = "cutdown", ignore = "fixture not distributed")]
fn native_dump_matches_the_c_library() {
    let mut s = SpecFluxFrame::new(spec("GHz"), flux());
    Frame::set_title(&mut s, "MyT").unwrap();
    s.perm_axes(&[2, 1]).unwrap();
    let text = native_dump(&starlink_ast::AnyObject::SpecFluxFrame(Box::new(s.clone()))).unwrap();
    let want = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/specfluxframe_swapped.native"
    ))
    .unwrap();
    assert_eq!(text, want);

    let starlink_ast::AnyObject::SpecFluxFrame(back) =
        starlink_ast::from_native_string(&text).unwrap()
    else {
        panic!("did not read back a SpecFluxFrame");
    };
    assert_eq!(back.title().unwrap(), "MyT");
    for axis in 1..=2 {
        assert_eq!(back.label(axis).unwrap(), s.label(axis).unwrap());
        assert_eq!(back.unit(axis).unwrap(), s.unit(axis).unwrap());
    }
    let text2 = native_dump(&starlink_ast::AnyObject::SpecFluxFrame(back)).unwrap();
    assert_eq!(text2, text);
}
